from pathlib import Path

import numpy as np
import pretty_midi

SR = 44100
SOUNDFONTS_GM = (
    Path("/usr/share/sounds/sf2/FluidR3_GM.sf2"),
    Path("/usr/share/sounds/sf2/default-GM.sf2"),
