)


class RenderizadorGM:
    def __init__(self, soundfont: Path | None = None):
        escolhido = soundfont or self.soundfont_padrao()
        if escolhido is None:
            raise FileNotFoundError(f"nenhum soundfont GM encontrado em {[str(s) for s in SOUNDFONTS_GM]}")
        self.soundfont = escolhido

    @staticmethod
    def soundfont_padrao() -> Path | None:
        return next((s for s in SOUNDFONTS_GM if s.exists()), None)

