import collections
import json
import re
import sys
from pathlib import Path

origem, destino = Path(sys.argv[1]), Path(sys.argv[2])

ATTACHMENTS_REMOVIDOS = {
    "instructions",
    "session_context",
    "skill_listing",
    "agent_listing_delta",
    "deferred_tools_delta",
    "deferred_tools_record",
    "mcp_instructions_delta",
    "credential_org",
    "prompt_snapshot",
}
MARCAS_DE_CONTEXTO = ("CLAUDE.md", "userEmail", "Skills pessoais", "deferred tools", "MCP Server Instructions", "available for use with the Skill tool")
PARCIAIS = ["[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]", "[arquivo pessoal]"]

linhas = [json.loads(l) for l in origem.open()]
contagem = collections.Counter()


def tool_use_da_downloads() -> set[str]:
    ids = set()
    for r in linhas:
        conteudo = r.get("message", {}).get("content")
        if r.get("type") == "assistant" and isinstance(conteudo, list):
            for bloco in conteudo:
                if bloco.get("type") == "tool_use" and "ls -la ~/downloads/" in json.dumps(bloco.get("input", {})):
                    ids.add(bloco["id"])
    return ids


IDS_DOWNLOADS = tool_use_da_downloads()
NOMES: set[str] = set()
for r in linhas:
    conteudo = r.get("message", {}).get("content")
    if r.get("type") == "user" and isinstance(conteudo, list):
        for bloco in conteudo:
            if bloco.get("type") == "tool_result" and bloco.get("tool_use_id") in IDS_DOWNLOADS:
                texto = json.dumps(bloco.get("content"), ensure_ascii=False)
                texto = texto.encode().decode("unicode_escape").encode("latin-1", "ignore").decode("utf-8", "ignore")
                for linha in texto.split("\n"):
                    m = re.match(r"^[d-][rwx-]{9}\s+\d+\s+\S+\s+\S+\s+\d+\s+\S+\s+\d+\s+\S+\s+(.+)$", linha.strip())
                    if m and m.group(1) not in (".", ".."):
                        NOMES.add(m.group(1).strip())
NOMES_ORDENADOS = sorted(NOMES, key=len, reverse=True)
PADRAO_EMAIL = re.compile(r"[\w.+-]+@[empresa]\.com\.br", re.I)
PADRAO_EMPRESA = re.compile(r"[empresa]", re.I)
PADRAO_REMINDER = re.compile(r"<system-reminder>.*?</system-reminder>", re.S)


def redigir(texto: str) -> str:
    novo = PADRAO_EMAIL.sub("[e-mail removido]", texto)
    for nome in NOMES_ORDENADOS:
        if len(nome) > 3 and nome in novo:
            novo = novo.replace(nome, "[arquivo pessoal]")
    for parcial in PARCIAIS:
        novo = novo.replace(parcial, "[arquivo pessoal]")

    def reminder(m: re.Match[str]) -> str:
        return "<system-reminder>[contexto do ambiente removido]</system-reminder>" if any(k in m.group(0) for k in MARCAS_DE_CONTEXTO) else m.group(0)

    novo = PADRAO_REMINDER.sub(reminder, novo)
    novo = PADRAO_EMPRESA.sub("[empresa]", novo)
    if novo != texto:
        contagem["strings redigidas"] += 1
    return novo


def percorrer(valor):
    if isinstance(valor, str):
        return redigir(valor)
    if isinstance(valor, list):
        return [percorrer(v) for v in valor]
    if isinstance(valor, dict):
        return {k: percorrer(v) for k, v in valor.items()}
    return valor


saida = []
for r in linhas:
    if r.get("type") == "attachment" and r.get("attachment", {}).get("type") in ATTACHMENTS_REMOVIDOS:
        tipo = r["attachment"]["type"]
        r = {**r, "attachment": {"type": tipo, "content": "[removido: contexto do ambiente do usuário]"}}
        contagem[f"attachment {tipo}"] += 1
    conteudo = r.get("message", {}).get("content")
    if r.get("type") == "user" and isinstance(conteudo, list):
        novos = []
        for bloco in conteudo:
            if bloco.get("type") == "tool_result" and bloco.get("tool_use_id") in IDS_DOWNLOADS:
                bloco = {**bloco, "content": "[saída removida: listagem da pasta ~/Downloads do usuário]"}
                contagem["resultado da listagem da Downloads"] += 1
            if bloco.get("type") == "text" and bloco.get("text", "").startswith("Base directory for this skill:"):
                nome = bloco["text"].split("/skills/")[1].split("\n")[0] if "/skills/" in bloco["text"] else "?"
                bloco = {**bloco, "text": f"[instruções da skill pessoal '{nome}' omitidas]"}
                contagem["texto de skill pessoal"] += 1
            novos.append(bloco)
        r = {**r, "message": {**r["message"], "content": novos}}
    if r.get("type") == "user" and isinstance(conteudo, str) and conteudo.startswith("Base directory for this skill:"):
        r = {**r, "message": {**r["message"], "content": "[instruções de skill pessoal omitidas]"}}
        contagem["texto de skill pessoal"] += 1
